function updateThemeButtons() {
    const buttonModes = {
        lightThemeBtn: 'light',
        systemThemeBtn: 'system',
        darkThemeBtn: 'dark'
    };
    Object.entries(buttonModes).forEach(([id, mode]) => {
        const button = document.getElementById(id);
        if (!button) return;
        const isActive = themeMode === mode;
        button.classList.toggle('active', isActive);
        button.setAttribute('aria-pressed', String(isActive));
    });
    updateThemeQuickButton();
}

/* lucide 图标工具：createIcons 会把 <i data-lucide> 整体替换为 <svg>，
   动态换图须先移除旧图标再重建 <i>，否则新图标不会生效 */
function setLucideIcon(container, name) {
    if (typeof lucide === 'undefined' || !lucide.createIcons) return;
    const old = container.querySelector('svg.lucide, [data-lucide]');
    if (old) old.remove();
    const el = document.createElement('i');
    el.setAttribute('data-lucide', name);
    container.appendChild(el);
    lucide.createIcons();
}
function renderLucideIcons() {
    if (typeof lucide !== 'undefined' && lucide.createIcons) lucide.createIcons();
}
/* 装备条目图标：icon 带 lucide: 前缀走 lucide，其余保持 Font Awesome */
function equipmentIconHtml(item) {
    if (item.icon && item.icon.indexOf('lucide:') === 0) {
        return `<i data-lucide="${item.icon.slice(7)}"></i>`;
    }
    return `<i class="fa-solid ${item.icon}"></i>`;
}

/* 顶栏快捷主题按钮：深色时显示太阳（点击切浅色），浅色时显示月亮（点击切深色） */
function updateThemeQuickButton() {
    const btn = document.getElementById('themeQuickBtn');
    if (!btn) return;
    setLucideIcon(btn, resolvedTheme === 'dark' ? 'sun' : 'moon');
}

function toggleThemeQuick() {
    setThemeMode(resolvedTheme === 'dark' ? 'light' : 'dark');
}

function applyThemeMode(mode, persist = true) {
    const nextMode = THEME_MODES.has(mode) ? mode : 'system';
    const nextTheme = resolveTheme(nextMode);
    const themeChanged = resolvedTheme !== nextTheme;
    themeMode = nextMode;
    resolvedTheme = nextTheme;
    chartTheme = chartThemePalettes[resolvedTheme];

    const root = document.documentElement;
    root.dataset.themeMode = themeMode;
    root.dataset.theme = resolvedTheme;
    root.style.colorScheme = resolvedTheme;
    if (typeof applyThemeColorMeta === 'function') applyThemeColorMeta(resolvedTheme);

    if (persist) {
        try {
            localStorage.setItem(THEME_STORAGE_KEY, themeMode);
        } catch (_) {}
    }

    updateThemeButtons();
    if (!themeChanged) return;

    chartThemeVersion++;
    if (typeof trackData !== 'undefined' && trackData && typeof drawChart === 'function' && chartCanvas) {
        drawChart({ segments: Array.isArray(allSegments) ? allSegments : [] });
    }
    if (typeof updateMapTileFilter === 'function') updateMapTileFilter();
}

function setThemeMode(mode) {
    applyThemeMode(mode, true);
}

function handleSystemThemeChange() {
    if (themeMode === 'system') applyThemeMode('system', false);
}

if (systemThemeMedia) {
    if (typeof systemThemeMedia.addEventListener === 'function') {
        systemThemeMedia.addEventListener('change', handleSystemThemeChange);
    } else {
        systemThemeMedia.addListener(handleSystemThemeChange);
    }
}

document.addEventListener('DOMContentLoaded', () => {
    renderLucideIcons();
    applyThemeMode(themeMode, false);
});

