const estimatedTimeCache = new WeakMap();
function estimateTime(data) {
    const cached = estimatedTimeCache.get(data);
    if (cached && cached.totalAscent === data.totalAscent && cached.totalDescent === data.totalDescent &&
        cached.pointCount === data.points.length) {
        return cached.value;
    }

    const { totalDistance, totalAscent, totalDescent, points } = data;

    const baseTime = (totalDistance / 5) * 60;
    const ascentTime = (totalAscent / 10);
    const descentTime = (totalDescent / 15);

    let steepDistance = 0;
    for (let i = 1; i < points.length; i++) {
        if (Math.abs(points[i].smoothedGradient) > 15) {
            steepDistance += points[i].distance - points[i - 1].distance;
        }
    }
    const STEEP_PACE_PENALTY = 4;
    const steepAdjust = steepDistance * STEEP_PACE_PENALTY;

    const totalWalkMin = baseTime + ascentTime + descentTime + steepAdjust;
    const restMin = totalWalkMin * 0.15;
    const totalMin = totalWalkMin + restMin;

    const value = {
        totalHours: totalMin / 60,
        walkHours: totalWalkMin / 60,
        restHours: restMin / 60,
        avgPace: totalMin / totalDistance,
        calories: Math.round(70 * (totalDistance * 0.7 + totalAscent * 0.0106))
    };
    estimatedTimeCache.set(data, { totalAscent, totalDescent, pointCount: points.length, value });
    return value;
}
function changePageSize() {
    const select = document.getElementById('pageSizeSelect');
    pageSize = parseInt(select.value);
    currentPage = 1;
    updateSegments();
}
function goToPage(page) {
    const totalPages = Math.ceil(totalSegments / pageSize);
    if (page >= 1 && page <= totalPages) {
        currentPage = page;
        updateSegments();
    }
}
function prevPage() {
    if (currentPage > 1) {
        currentPage--;
        updateSegments();
    }
}
function nextPage() {
    const totalPages = Math.ceil(totalSegments / pageSize);
    if (currentPage < totalPages) {
        currentPage++;
        updateSegments();
    }
}
function goToLastPage() {
    const totalPages = Math.ceil(totalSegments / pageSize);
    goToPage(totalPages);
}
const fileNameHoverMedia = window.matchMedia?.('(hover: hover) and (pointer: fine)') ?? null;
