    if (overlay.width !== width || overlay.height !== height || overlay._dpr !== dpr) {
        overlay.width = width;
        overlay.height = height;
        overlay._dpr = dpr;
    }
    const ctx = overlay.getContext('2d');
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
